	}

	const fileTok = readJson(tokenPath);
	const krTok = store.getTokenCache();
	if (fileTok && Object.keys(fileTok).length > 0 && Object.keys(krTok).length === 0) {
		await store.saveTokenCache(fileTok as TokenCache);
