	if (lib) {
		const readLegacy = (account: string): SecretBlob => {
			try {
				const raw = new lib.Entry(LEGACY_SERVICE, account).getPassword();
				return raw ? (JSON.parse(raw) as SecretBlob) : null;
			} catch {
